content.text:
{
  "name": "串口I/O从控器",
  "name_en": "Serial I/O Slave Controller",
  "manufacturer": "",
  "description": "一种通过串口通信的通用实验室I/O控制器，可按通道提供数字输出、模拟输出、模拟量读取和温度读取功能。常用于显微镜及其他实验装置中的外设联动、传感器采集和简单执行器控制。",
  "description_en": "A general-purpose laboratory I/O controller that communicates over a serial port and provides channel-based digital output, analog output, analog readback, and temperature readout. It is commonly used in microscopes and other experimental setups for peripheral coordination, sensor acquisition, and simple actuator control.",
  "actions": [
    {
      "action_name": "auto-SetDigital",
      "description": "设置指定通道的数字输出状态。",
      "description_en": "Set the digital output state of the specified channel."
    },
    {
      "action_name": "auto-SetAnalog",
      "description": "设置指定通道的模拟输出值。",
      "description_en": "Set the analog output value of the specified channel."
    },
    {
      "action_name": "auto-SetFlash",
      "description": "设置指定通道的闪光输出值。",
      "description_en": "Set the flash output value of the specified channel."
    },
    {
      "action_name": "auto-GetAnalog",
      "description": "读取指定通道的模拟输入值。",
      "description_en": "Read the analog input value of the specified channel."
    },
    {
      "action_name": "auto-GetTemperature",
      "description": "读取指定通道的温度值。",
      "description_en": "Read the temperature value of the specified channel."
    }
  ],
  "tag_hints": [
    "serial I/O control",
    "digital output",
    "analog output",
    "analog input",
    "temperature sensing",
    "instrument automation",
    "microscope hardware control"
  ]
}

